				type: "save-finished",
				notice: `${provider.name} ${isEdit ? "updated" : "saved"}.${discoveryWarning}`,
			});
		} catch (error) {
			console.error("Failed to save provider:", error);
			const message = error instanceof Error ? error.message : "Unknown connection error";
